CREATE TYPE "MediaType" AS ENUM ('MOVIE', 'SERIES');
CREATE TYPE "MediaImageType" AS ENUM ('POSTER', 'BACKDROP', 'LOGO', 'THUMBNAIL');
CREATE TYPE "CreditType" AS ENUM ('ACTOR', 'DIRECTOR', 'WRITER', 'PRODUCER');
CREATE TYPE "PlaybackProtocol" AS ENUM ('HLS', 'DASH', 'MPEG_TS', 'FILE', 'REMOTE_REFERENCE');

CREATE TABLE "MediaTitle" ("id" TEXT NOT NULL, "slug" TEXT NOT NULL, "type" "MediaType" NOT NULL, "names" JSONB NOT NULL, "alternativeNames" JSONB, "searchText" TEXT NOT NULL, "synopsis" JSONB, "originalLanguage" TEXT, "countryCodes" TEXT[] NOT NULL, "releaseYear" INTEGER, "ageRating" TEXT, "rating" DECIMAL(3,1), "trailerUrl" TEXT, "status" "PublicationStatus" NOT NULL DEFAULT 'DRAFT', "featured" BOOLEAN NOT NULL DEFAULT false, "publishedAt" TIMESTAMP(3), "scheduledFor" TIMESTAMP(3), "archivedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "MediaTitle_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Movie" ("mediaTitleId" TEXT NOT NULL, "durationSec" INTEGER NOT NULL, CONSTRAINT "Movie_pkey" PRIMARY KEY ("mediaTitleId"));
CREATE TABLE "Series" ("mediaTitleId" TEXT NOT NULL, "seriesStatus" TEXT, CONSTRAINT "Series_pkey" PRIMARY KEY ("mediaTitleId"));
CREATE TABLE "Season" ("id" TEXT NOT NULL, "seriesId" TEXT NOT NULL, "seasonNumber" INTEGER NOT NULL, "names" JSONB, "synopsis" JSONB, "releaseYear" INTEGER, "sortOrder" INTEGER NOT NULL DEFAULT 0, CONSTRAINT "Season_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Episode" ("id" TEXT NOT NULL, "seasonId" TEXT NOT NULL, "episodeNumber" INTEGER NOT NULL, "names" JSONB NOT NULL, "synopsis" JSONB, "durationSec" INTEGER, "airedAt" TIMESTAMP(3), "sortOrder" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Episode_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Genre" ("id" TEXT NOT NULL, "slug" TEXT NOT NULL, "names" JSONB NOT NULL, "sortOrder" INTEGER NOT NULL DEFAULT 0, "active" BOOLEAN NOT NULL DEFAULT true, CONSTRAINT "Genre_pkey" PRIMARY KEY ("id"));
CREATE TABLE "MediaTitleGenre" ("mediaTitleId" TEXT NOT NULL, "genreId" TEXT NOT NULL, CONSTRAINT "MediaTitleGenre_pkey" PRIMARY KEY ("mediaTitleId","genreId"));
CREATE TABLE "Person" ("id" TEXT NOT NULL, "displayName" TEXT NOT NULL, "sortName" TEXT NOT NULL, "biography" JSONB, "photoUrl" TEXT, CONSTRAINT "Person_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Credit" ("id" TEXT NOT NULL, "mediaTitleId" TEXT NOT NULL, "personId" TEXT NOT NULL, "type" "CreditType" NOT NULL, "character" TEXT, "sortOrder" INTEGER NOT NULL DEFAULT 0, CONSTRAINT "Credit_pkey" PRIMARY KEY ("id"));
CREATE TABLE "MediaImage" ("id" TEXT NOT NULL, "mediaTitleId" TEXT, "episodeId" TEXT, "type" "MediaImageType" NOT NULL, "url" TEXT NOT NULL, "languageCode" TEXT, "width" INTEGER, "height" INTEGER, "sortOrder" INTEGER NOT NULL DEFAULT 0, CONSTRAINT "MediaImage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ExternalId" ("id" TEXT NOT NULL, "provider" TEXT NOT NULL, "externalId" TEXT NOT NULL, "mediaTitleId" TEXT, "episodeId" TEXT, CONSTRAINT "ExternalId_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PlaybackVariant" ("id" TEXT NOT NULL, "mediaTitleId" TEXT, "episodeId" TEXT, "channelId" TEXT, "label" TEXT NOT NULL, "protocol" "PlaybackProtocol" NOT NULL, "reference" TEXT NOT NULL, "quality" TEXT, "videoCodec" TEXT, "audioCodec" TEXT, "languageCode" TEXT, "regionCodes" TEXT[] NOT NULL, "priority" INTEGER NOT NULL DEFAULT 100, "enabled" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PlaybackVariant_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "MediaTitle_slug_key" ON "MediaTitle"("slug"); CREATE INDEX "MediaTitle_type_status_releaseYear_idx" ON "MediaTitle"("type","status","releaseYear"); CREATE INDEX "MediaTitle_featured_publishedAt_idx" ON "MediaTitle"("featured","publishedAt");
CREATE UNIQUE INDEX "Season_seriesId_seasonNumber_key" ON "Season"("seriesId","seasonNumber"); CREATE INDEX "Season_seriesId_sortOrder_idx" ON "Season"("seriesId","sortOrder");
CREATE UNIQUE INDEX "Episode_seasonId_episodeNumber_key" ON "Episode"("seasonId","episodeNumber"); CREATE INDEX "Episode_seasonId_sortOrder_idx" ON "Episode"("seasonId","sortOrder");
CREATE UNIQUE INDEX "Genre_slug_key" ON "Genre"("slug"); CREATE INDEX "Person_sortName_idx" ON "Person"("sortName");
CREATE UNIQUE INDEX "Credit_mediaTitleId_personId_type_character_key" ON "Credit"("mediaTitleId","personId","type","character"); CREATE INDEX "Credit_mediaTitleId_type_sortOrder_idx" ON "Credit"("mediaTitleId","type","sortOrder");
CREATE INDEX "MediaImage_mediaTitleId_type_sortOrder_idx" ON "MediaImage"("mediaTitleId","type","sortOrder"); CREATE INDEX "MediaImage_episodeId_type_sortOrder_idx" ON "MediaImage"("episodeId","type","sortOrder");
CREATE UNIQUE INDEX "ExternalId_provider_externalId_key" ON "ExternalId"("provider","externalId"); CREATE INDEX "ExternalId_mediaTitleId_idx" ON "ExternalId"("mediaTitleId"); CREATE INDEX "ExternalId_episodeId_idx" ON "ExternalId"("episodeId");
CREATE INDEX "PlaybackVariant_mediaTitleId_enabled_priority_idx" ON "PlaybackVariant"("mediaTitleId","enabled","priority"); CREATE INDEX "PlaybackVariant_episodeId_enabled_priority_idx" ON "PlaybackVariant"("episodeId","enabled","priority"); CREATE INDEX "PlaybackVariant_channelId_enabled_priority_idx" ON "PlaybackVariant"("channelId","enabled","priority");
ALTER TABLE "Movie" ADD CONSTRAINT "Movie_mediaTitleId_fkey" FOREIGN KEY ("mediaTitleId") REFERENCES "MediaTitle"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Series" ADD CONSTRAINT "Series_mediaTitleId_fkey" FOREIGN KEY ("mediaTitleId") REFERENCES "MediaTitle"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Season" ADD CONSTRAINT "Season_seriesId_fkey" FOREIGN KEY ("seriesId") REFERENCES "Series"("mediaTitleId") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Episode" ADD CONSTRAINT "Episode_seasonId_fkey" FOREIGN KEY ("seasonId") REFERENCES "Season"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "MediaTitleGenre" ADD CONSTRAINT "MediaTitleGenre_mediaTitleId_fkey" FOREIGN KEY ("mediaTitleId") REFERENCES "MediaTitle"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "MediaTitleGenre" ADD CONSTRAINT "MediaTitleGenre_genreId_fkey" FOREIGN KEY ("genreId") REFERENCES "Genre"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Credit" ADD CONSTRAINT "Credit_mediaTitleId_fkey" FOREIGN KEY ("mediaTitleId") REFERENCES "MediaTitle"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Credit" ADD CONSTRAINT "Credit_personId_fkey" FOREIGN KEY ("personId") REFERENCES "Person"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "MediaImage" ADD CONSTRAINT "MediaImage_mediaTitleId_fkey" FOREIGN KEY ("mediaTitleId") REFERENCES "MediaTitle"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "MediaImage" ADD CONSTRAINT "MediaImage_episodeId_fkey" FOREIGN KEY ("episodeId") REFERENCES "Episode"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ExternalId" ADD CONSTRAINT "ExternalId_mediaTitleId_fkey" FOREIGN KEY ("mediaTitleId") REFERENCES "MediaTitle"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "ExternalId" ADD CONSTRAINT "ExternalId_episodeId_fkey" FOREIGN KEY ("episodeId") REFERENCES "Episode"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "PlaybackVariant" ADD CONSTRAINT "PlaybackVariant_mediaTitleId_fkey" FOREIGN KEY ("mediaTitleId") REFERENCES "MediaTitle"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "PlaybackVariant" ADD CONSTRAINT "PlaybackVariant_episodeId_fkey" FOREIGN KEY ("episodeId") REFERENCES "Episode"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "PlaybackVariant" ADD CONSTRAINT "PlaybackVariant_channelId_fkey" FOREIGN KEY ("channelId") REFERENCES "Channel"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "MediaImage" ADD CONSTRAINT "MediaImage_exactly_one_owner" CHECK ((CASE WHEN "mediaTitleId" IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN "episodeId" IS NOT NULL THEN 1 ELSE 0 END) = 1);
ALTER TABLE "ExternalId" ADD CONSTRAINT "ExternalId_exactly_one_owner" CHECK ((CASE WHEN "mediaTitleId" IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN "episodeId" IS NOT NULL THEN 1 ELSE 0 END) = 1);
ALTER TABLE "PlaybackVariant" ADD CONSTRAINT "PlaybackVariant_exactly_one_owner" CHECK ((CASE WHEN "mediaTitleId" IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN "episodeId" IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN "channelId" IS NOT NULL THEN 1 ELSE 0 END) = 1);
